        var today = nowPartsForOffset();
        var html = '<div class="tb-utc-months">';
        monthNames.forEach(function (m, idx) {
            var cls = ['tb-utc-month'];
            if (idx === today.m && currentYear === today.y) cls.push('tb-utc-today');
