            ? Date.now()
            : endOfYearMs(year);
        applyTimewindow(s, e, MONTH_MS);

        if (dayValue) dayValue.textContent = 'Day';
        if (monthValue) monthValue.textContent = 'Month';
        if (yearValue) yearValue.textContent = String(year);
