    if (monthValue) monthValue.textContent = lastSelectedMode === 'year' ? 'Month' : monthNames[currentMonth];
    if (dayValue) dayValue.textContent = (lastSelectedMode === 'year' || lastSelectedMode === 'month') ? 'Day' : String(currentDay);
